/**
 * A session's lifecycle state.
 */
export enum SessionState {
    /**
     * The desktop is starting or waking.
     */
    Starting,
    /**
     * The desktop is up.
     */
    Running,
    /**
     * The desktop is shutting down: a stop, a sleep or a delete.
     */
    Stopping,
    /**
     * No compute; disk and snapshot kept. An MCP call wakes it.
     */
    Asleep,
    /**
     * Stopped on request; disk kept. An MCP call answers 409.
     */
    Stopped,
    /**
     * The desktop could not start; `message` says why.
     */
    Failed,
    /**
     * A state this version of the SDK does not know.
     */
    Unknown
}

const FfiConverterTypeSessionState = (() => {
    type TypeName = SessionState;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        readFromCursor(c: Cursor): TypeName {
            switch (c.readI32()) {
                case 1: return SessionState.Starting;
                case 2: return SessionState.Running;
                case 3: return SessionState.Stopping;
                case 4: return SessionState.Asleep;
                case 5: return SessionState.Stopped;
                case 6: return SessionState.Failed;
                case 7: return SessionState.Unknown;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        writeIntoCursor(value: TypeName, c: Cursor): void {
            switch (value) {
                case SessionState.Starting: return c.writeI32(1);
                case SessionState.Running: return c.writeI32(2);
                case SessionState.Stopping: return c.writeI32(3);
                case SessionState.Asleep: return c.writeI32(4);
                case SessionState.Stopped: return c.writeI32(5);
                case SessionState.Failed: return c.writeI32(6);
                case SessionState.Unknown: return c.writeI32(7);
            }
        }
        allocationSize(value: TypeName): number {
            return 4;
        }
    }
    return new FFIConverter();
})();

